def run(inputs: dict) -> dict:
    import numpy as np

    metrics = inputs.get("ExtractedMetric", [])
    if not metrics:
        raise ValueError("Нет данных ExtractedMetric")

    values = []
    units = set()
    for m in metrics:
        sf = m.get("scalar_fact")
        if sf is None:
            continue
        if sf.get("concept") != "SALES_REVENUE":
            continue
        v = sf.get("value")
        u = sf.get("unit")
        if v is None or u is None:
            continue
        values.append(v)
        units.add(u)

    if not values:
        raise ValueError("Нет значений SALES_REVENUE")
    if len(units) != 1:
        raise ValueError(f"Несовместимые единицы: {units}")

    arr = np.array(values, dtype=float)
    mean = float(np.mean(arr))
    std_dev = float(np.std(arr, ddof=0))
    if mean == 0:
        raise ValueError("Среднее равно нулю, CV не определён")
    cv = (std_dev / mean) * 100.0

    return {
        "mean": mean,
        "std_dev": std_dev,
        "coefficient_of_variation": cv,
    }
